// ดึงข้อมูลจาก Editor Agent และเตรียม Video Script
const sheet = $('เตรียมข้อมูล').first().json;
const editorRaw = $('Editor Agent1').first().json;
const rawText = editorRaw.output?.[0]?.content?.[0]?.text
  || editorRaw.message?.content || '';

let editorResult = {};
try {
  const cleaned = rawText
    .replace(/^```json\n?/i, '')
    .replace(/^```\n?/i, '')
    .replace(/\n?```$/i, '')
    .trim();
  editorResult = JSON.parse(cleaned);
} catch(e) {}

const productName = (sheet['product_name'] || '').replace(/^=+/, '').trim();
const price = String(sheet['price'] || '').replace(/^=+/, '').trim();
const rating = editorResult.rating || 4.0;
const ratingDisplay = typeof rating === 'number' ? rating.toFixed(1) : String(rating);
const categoryName = sheet['category'] || '';
const highlights = sheet['highlights'] || '';

const highlightList = highlights.split(',').map(s => s.trim()).filter(Boolean);
const top2 = highlightList.slice(0, 2).join(' และ ');
const top3Pros = highlightList.slice(0, 3);

// สร้าง narration ภาษาไทยสำหรับ TTS
const narration = [
  `วันนี้เรามารีวิว ${productName}${price ? ' ราคา ' + price + ' บาท' : ''}`,
  categoryName ? `สินค้าหมวด${categoryName}` : '',
  top2 ? `จุดเด่นของสินค้านี้คือ ${top2}` : '',
  `คะแนนรวมจาก KaoShop อยู่ที่ ${ratingDisplay} จาก 5 คะแนน`,
  `ดูรีวิวเต็มและราคาล่าสุดได้ที่ KaoShop
`
].filter(Boolean).join(' ');

// รูปจาก Cloudinary (ใช้รูป jpg เพื่อความเข้ากันได้กับ Shotstack)
const toJpg = (url) => {
  if (!url) return '';
  return url.replace('/upload/', '/upload/f_jpg,c_fill,w_1280,h_720/');
};

const img1 = toJpg($('แปลงรูป Cloudinary1').first().json?.secure_url || '');
const img2 = toJpg($('แปลงรูป Cloudinary4').first().json?.secure_url || '') || img1;
const img3 = toJpg($('แปลงรูป Cloudinary5').first().json?.secure_url || '') || img1;

console.log(`Video Script สำหรับ: ${productName}`);
console.log(`Narration (${narration.length} chars): ${narration.substring(0, 100)}...`);

return [{
  json: {
    narration,
    productName,
    price,
    rating: ratingDisplay,
    categoryName,
    img1, img2, img3,
    top3Pros
  }
}];

