// สร้าง Shotstack render body แบบครบวงจร
const script = $('สร้าง Video Script1').first().json;
const audioUrl = $('Upload Audio Cloudinary1').first().json?.secure_url || '';

const { productName, price, rating, img1, img2, img3, top3Pros } = script;

// Helper: escape HTML special chars
const esc = (s) => String(s || '')
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

// Slide 1: แนะนำสินค้า (0-5 วิ)
const slide1Html = `<div style="font-family:Arial,Helvetica,sans-serif;color:#ffffff;background:linear-gradient(135deg,rgba(0,0,0,0.85),rgba(20,20,60,0.85));padding:18px 28px;border-radius:12px;text-align:center;border:2px solid rgba(255,255,255,0.2)">
  <p style="margin:0 0 6px;font-size:32px;font-weight:bold;line-height:1.3">${esc(productName)}</p>
  ${price ? `<p style="margin:0;font-size:22px;color:#ffd700">฿${esc(price)}</p>` : ''}
</div>`;

// Slide 2: จุดเด่นสินค้า (5-10 วิ)
const prosHtml = (top3Pros || []).slice(0, 3)
  .map(p => `<li style="margin:0 0 8px;font-size:17px">✓ ${esc(p)}</li>`)
  .join('') || '<li style="font-size:17px">✓ คุณภาพดีเยี่ยม</li>';

const slide2Html = `<div style="font-family:Arial,Helvetica,sans-serif;color:#ffffff;background:rgba(5,100,40,0.88);padding:18px 24px;border-radius:12px;border-left:5px solid #4ade80">
  <p style="margin:0 0 10px;font-size:19px;font-weight:bold;color:#4ade80">จุดเด่นที่คุณต้องรู้</p>
  <ul style="margin:0;padding:0;list-style:none">${prosHtml}</ul>
</div>`;

// Slide 3: คะแนน (10-15 วิ)
const ratingNum = parseFloat(rating) || 4.0;
const stars = '★'.repeat(Math.round(ratingNum)) + '☆'.repeat(5 - Math.round(ratingNum));
const slide3Html = `<div style="font-family:Arial,Helvetica,sans-serif;color:#ffffff;background:rgba(0,0,0,0.82);padding:22px 36px;border-radius:14px;text-align:center;border:2px solid rgba(251,191,36,0.6)">
  <p style="margin:0 0 4px;font-size:16px;letter-spacing:1px;text-transform:uppercase;opacity:0.8">คะแนน KaoShop</p>
  <p style="margin:0;font-size:58px;font-weight:bold;color:#fbbf24;line-height:1">${esc(rating)}</p>
  <p style="margin:2px 0 6px;font-size:14px;opacity:0.7">จาก 5.0</p>
  <p style="margin:0;font-size:22px;color:#fbbf24">${stars}</p>
</div>`;

// Slide 4: CTA ซื้อสินค้า (15-20 วิ)
const slide4Html = `<div style="font-family:Arial,Helvetica,sans-serif;color:#ffffff;background:rgba(234,88,12,0.92);padding:18px 36px;border-radius:12px;text-align:center">
  <p style="margin:0 0 4px;font-size:26px;font-weight:bold">🛒 ซื้อได้ที่ Shopee</p>
  <p style="margin:0;font-size:15px;opacity:0.9">ดูรีวิวเต็ม + ราคาล่าสุดที่ KaoShop.com</p>
</div>`;

// สร้าง Shotstack timeline
const renderBody = {
  timeline: {
    soundtrack: audioUrl ? {
      src: audioUrl,
      effect: 'fadeOut',
      volume: 1.0
    } : undefined,
    background: '#0a0a0a',
    tracks: [
      {
        // Track 1: Text overlay (ชั้นบน)
        clips: [
          {
            asset: { type: 'html', html: slide1Html, width: 900, height: 130 },
            start: 0.5, length: 4,
            position: 'bottom',
            offset: { x: 0, y: 0.08 },
            transition: { in: 'fade', out: 'fade' }
          },
          {
            asset: { type: 'html', html: slide2Html, width: 860, height: 180 },
            start: 5.5, length: 4,
            position: 'bottom',
            offset: { x: 0, y: 0.05 },
            transition: { in: 'fade', out: 'fade' }
          },
          {
            asset: { type: 'html', html: slide3Html, width: 380, height: 210 },
            start: 10.5, length: 4,
            position: 'center',
            transition: { in: 'fade', out: 'fade' }
          },
          {
            asset: { type: 'html', html: slide4Html, width: 800, height: 110 },
            start: 15.5, length: 4,
            position: 'bottom',
            offset: { x: 0, y: 0.08 },
            transition: { in: 'fade', out: 'fade' }
          }
        ]
      },
      {
        // Track 2: Background images (ชั้นล่าง)
        clips: [
          {
            asset: { type: 'image', src: img1 },
            start: 0, length: 5,
            fit: 'cover',
            effect: 'zoomIn',
            transition: { in: 'fade', out: 'fade' }
          },
          {
            asset: { type: 'image', src: img2 || img1 },
            start: 5, length: 5,
            fit: 'cover',
            effect: 'slideLeft',
            transition: { in: 'fade', out: 'fade' }
          },
          {
            asset: { type: 'image', src: img3 || img1 },
            start: 10, length: 5,
            fit: 'cover',
            effect: 'zoomOut',
            transition: { in: 'fade', out: 'fade' }
          },
          {
            asset: { type: 'image', src: img1 },
            start: 15, length: 5,
            fit: 'cover',
            effect: 'slideRight',
            transition: { in: 'fade', out: 'fade' }
          }
        ]
      }
    ]
  },
  output: {
    format: 'mp4',
    resolution: 'hd',
    fps: 25,
    size: { width: 1280, height: 720 }
  }
};

console.log(`Shotstack render body สำหรับ: ${productName}`);

return [{ json: { renderBody, productName } }];

// ดึง output จาก Editor Agent
const editorRaw = $('Editor Agent1').first().json;
const rawText = editorRaw.output?.[0]?.content?.[0]?.text
  || editorRaw.message?.content || '';

const cleaned = rawText
  .replace(/^```json\n?/i, '')
  .replace(/^```\n?/i, '')
  .replace(/\n?```$/i, '')
  .trim();

let editorResult = {};
try {
  editorResult = JSON.parse(cleaned);
} catch(e) {
  editorResult = { content: cleaned };
}

const htmlContent = editorResult.content || cleaned;
const rating = editorResult.rating || null;
const scoreBreakdown = editorResult.scoreBreakdown || null;

// ดึงข้อมูลจาก Sheet
const sheet = $('เตรียมข้อมูล').first().json;
const productName = (sheet['product_name'] || '').replace(/^=+/, '').trim();
const price = String(sheet['price'] || '').replace(/^=+/, '').trim();
const affiliateUrl = sheet['affiliate_url'] || '';
const categoryName = sheet['category'] || 'ทั่วไป';

// ดึง Video URL จาก Shotstack (mp4 พร้อม AI voice + text overlay)
const shotstackResp = $('เช็คสถานะ Shotstack1').first().json;
const videoUrl = shotstackResp?.response?.url || null;

if (videoUrl) {
  console.log(`Video URL (Shotstack): ${videoUrl}`);
} else {
  console.log('ไม่มี video URL จาก Shotstack:', JSON.stringify(shotstackResp));
}

// ดึงรูปจาก Cloudinary
const img1 = $('แปลงรูป Cloudinary1').first().json?.secure_url || '';
const img2 = $('แปลงรูป Cloudinary4').first().json?.secure_url || '';
const img3 = $('แปลงรูป Cloudinary5').first().json?.secure_url || '';
const images = [img1, img2, img3].filter(Boolean);

const baseSlug = productName
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .replace(/\s+/g, '-')
  .replace(/-+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 60);

const slug = (baseSlug || 'article') + '-' + Date.now();

const prosRaw = sheet['pros'] || '';
const consRaw = sheet['cons'] || '';
const pros = prosRaw ? prosRaw.split(',').map(s => s.trim()).filter(Boolean) : [];
const cons = consRaw ? consRaw.split(',').map(s => s.trim()).filter(Boolean) : [];

const title = editorResult.title
  || `รีวิว ${productName}${price ? ' ราคา ' + price + ' บาท' : ''}`;

const excerpt = `รีวิวครบ ${productName} พร้อมข้อดี-ข้อเสีย คะแนน ${rating ? rating.toFixed(1) : '?'}/5 และความคุ้มค่าราคา`;

return [{
  json: {
    title,
    slug,
    excerpt,
    content: htmlContent,
    featuredImage: images[0] || null,
    images,
    rating,
    scoreBreakdown,
    pros,
    cons,
    affiliateUrl,
    price: String(price),
    productName,
    categoryName,
    categorySlug: categoryName.toLowerCase().replace(/\s+/g, '-'),
    videoUrl: videoUrl || null,
    published: true,
  }
}];
